    int i = 2;
    for (int j = 2; j < nums.length; j++) {
      if (nums[j] != nums[i - 2]) {
        nums[i] = nums[j];
        i++;
      }
    }
    return i;
  }
}

class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        if len(nums) <= 2:
            return len(nums)
        i = 2
        for j in range(2, len(nums)):
            if nums[j] != nums[i - 2]:
                nums[i] = nums[j]
                i += 1
        return i

impl Solution {
  pub fn remove_duplicates(nums: &mut Vec<i32>) -> i32 {
    if nums.len() <= 2 {
      return nums.len() as i32;
    }
    let mut i = 2;
    for j in 2..nums.len() {
      if nums[j] != nums[i - 2] {
        nums[i] = nums[j];
        i += 1;
      }
    }
    i as i32
  }
}

const removeDuplicates = (nums: number[]): number => {
  if (nums.length <= 2) return nums.length;
  let i = 2;
  for (let j = 2; j < nums.length; j++) {
    if (nums[j] !== nums[i - 2]) {
      nums[i] = nums[j];
      i++;
    }
  }
  return i;
};
